} catch {
  tab = await browser.tabs.create("http://localhost:8080/uploads/videos/drama-01/ep-01.mp4");
}
await tab.goto("http://localhost:8080/uploads/videos/drama-01/ep-01.mp4");
await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
await tab.playwright.waitForTimeout(2500);
const videoState = await tab.playwright.evaluate(() => {
  const v = document.querySelector("video");
  if (!v) return { found: false, bodyChildren: document.body ? document.body.children.length : 0 };
  return {
    found: true,
    readyState: v.readyState,
    networkState: v.networkState,
    duration: v.duration,
    videoWidth: v.videoWidth,
    videoHeight: v.videoHeight,
    error: v.error ? v.error.code : null,
  };
});
videoState;

