} catch {
  tab = await browser.tabs.create("http://localhost:3000/");
}
await tab.goto("http://localhost:3000/");
await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
await tab.playwright.waitForTimeout(1500);
const result = await tab.playwright.evaluate(async () => {
  const loadVideo = (src) =>
    new Promise((resolve) => {
      const v = document.createElement("video");
      v.src = src;
      v.preload = "auto";
      v.muted = true;
      const timer = setTimeout(() => resolve({ src, ok: false, reason: "timeout-8s" }), 8000);
      v.addEventListener("loadeddata", () => {
        clearTimeout(timer);
        resolve({
          src,
          ok: true,
          readyState: v.readyState,
          duration: Math.round(v.duration * 10) / 10,
          width: v.videoWidth,
          height: v.videoHeight,
        });
      });
      v.addEventListener("error", () => {
        clearTimeout(timer);
        resolve({ src, ok: false, reason: v.error ? v.error.code : "unknown" });
      });
      v.load();
    });
  const proxy = await loadVideo("/uploads/videos/drama-01/ep-01.mp4");
  const direct = await loadVideo("http://localhost:8080/uploads/videos/drama-01/ep-01.mp4");
  return { proxy, direct };
});
result;

